using System;using System.Linq;using UnityEngine;using UnityEngine.SceneManagement;using VRC.Core;using VRC.SDK3.Avatars.Components;using MorphForge.Editor;using Newtonsoft.Json.Linq;
public static class Mf6Identity{public static string Inspect(){var scene=SceneManager.GetSceneByPath(Mf6AvatarBuild.ScenePath);var avatar=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VRCAvatarDescriptor>(true)).Single();return new JObject{["scene"]=scene.path,["dirty"]=scene.isDirty,["name"]=avatar.name,["sceneAvatarId"]=avatar.GetComponent<PipelineManager>().blueprintId,["prefabAvatarId"]=Mf6AvatarBuild.AvatarId}.ToString();}}
